// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetConsultByAppointment The consult session of one of my online appointments
	// (GET /v1/appointments/{appointmentId}/consult)
	GetConsultByAppointment(ctx context.Context, request GetConsultByAppointmentRequestObject) (GetConsultByAppointmentResponseObject, error)
	// GetConsult A consult session (the doctor also sees the patient's name and age, for identification)
	// (GET /v1/consults/{consultId})
	GetConsult(ctx context.Context, request GetConsultRequestObject) (GetConsultResponseObject, error)
	// ConfirmConsultIdentity The doctor confirms the patient's name and age (P02); the composer opens only after this
	// (POST /v1/consults/{consultId}/identity-confirmation)
	ConfirmConsultIdentity(ctx context.Context, request ConfirmConsultIdentityRequestObject) (ConfirmConsultIdentityResponseObject, error)
	// JoinConsult Get a short-lived join token for the room (only within the window around the slot)
	// (POST /v1/consults/{consultId}/join)
	JoinConsult(ctx context.Context, request JoinConsultRequestObject) (JoinConsultResponseObject, error)
	// ReportConsultMinor The doctor finds the patient is a minor; the consult stops and the account is flagged (TC-48)
	// (POST /v1/consults/{consultId}/minor-discovered)
	ReportConsultMinor(ctx context.Context, request ReportConsultMinorRequestObject) (ReportConsultMinorResponseObject, error)
	// ChangeConsultMode Record that the call dropped from video to audio
	// (POST /v1/consults/{consultId}/mode-changes)
	ChangeConsultMode(ctx context.Context, request ChangeConsultModeRequestObject) (ChangeConsultModeResponseObject, error)
	// SetConsultOutcome End the consult with an outcome
	// (POST /v1/consults/{consultId}/outcome)
	SetConsultOutcome(ctx context.Context, request SetConsultOutcomeRequestObject) (SetConsultOutcomeResponseObject, error)
	// PreJoinConsult Record the device check and the teleconsultation consent for this consult
	// (POST /v1/consults/{consultId}/pre-join)
	PreJoinConsult(ctx context.Context, request PreJoinConsultRequestObject) (PreJoinConsultResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

